// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0) && recipient != address(this) && recipient != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 ownerBalanceBefore = address(this).balance;
        c.withdrawAll(recipient);
        uint256 ownerBalanceAfter = address(this).balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore);
    }
}
